export interface StreamEndMessage {
  type: 'stream_end';
}

export interface SessionSummaryFrame {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}

export interface SessionListMessage {
  type: 'session_list';
  sessions: SessionSummaryFrame[];
}

export type OutgoingMessage =
  | ConnectedMessage
  | EntryUpsertMessage
  | EntryDeltaMessage
  | EntryCommitMessage
  | EntrySkipMessage
  | ErrorMessage
  | PongMessage
  | StreamEndMessage
  | SessionListMessage;

export {ErrorCodes} from './session.js';

import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_SESSION_ID_LENGTH = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = parseLimit(message.limit);
  if (limit === null) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  const cursor = parseCursor(message.before);
  if (cursor === null) {
    return {valid: false, error: 'list_sessions before must have a 1-128 char sessionId and valid updatedAt'};
  }

  const validated: ListSessionsMessage = {type: 'list_sessions'};
  if (limit !== undefined) validated.limit = limit;
  if (cursor !== undefined) validated.before = cursor;

  return {valid: true, data: validated};
}

function parseLimit(limit: unknown): number | undefined | null {
  if (limit === undefined) return undefined;
  if (typeof limit !== 'number') return null;
  return Number.isInteger(limit) && limit >= 0 ? limit : null;
}

function parseCursor(rawCursor: unknown): SessionCursor | undefined | null {
  if (rawCursor === undefined) return undefined;
  if (typeof rawCursor !== 'object' || rawCursor === null) return null;
  if (Array.isArray(rawCursor)) return null;

  const {sessionId, updatedAt} = rawCursor as Record<string, unknown>;
  if (!isValidSessionId(sessionId) || !isValidUpdatedAt(updatedAt)) return null;

  return {updatedAt, sessionId};
}

function isValidSessionId(sessionId: unknown): sessionId is string {
  if (typeof sessionId !== 'string') return false;
  return sessionId.length >= 1 && sessionId.length <= MAX_SESSION_ID_LENGTH;
}

function isValidUpdatedAt(updatedAt: unknown): updatedAt is string | number {
  if (typeof updatedAt === 'string') {
    return updatedAt.trim().length > 0 && Number.isFinite(Date.parse(updatedAt));
  }
  if (typeof updatedAt === 'number') {
    return Number.isFinite(updatedAt) && Number.isFinite(new Date(updatedAt).getTime());
  }
  return false;
}

